'use strict';
const modelHeldKeys=new Map();
function modelJavaCode(action){return action?.startsWith('digit:')?action.slice(6).charCodeAt(0):({'dir:up':-1,'dir:down':-2,'dir:left':-3,'dir:right':-4,ok:-5,'soft:left':-6,'soft:right':-7})[action];}
function modelReleasePointer(id){const held=modelHeldKeys.get(id);if(!held)return;modelHeldKeys.delete(id);held.el.classList.remove('is-held');if(![...modelHeldKeys.values()].some(k=>k.code===held.code))pocketJavaMessage('key',held.code,false);}
function modelReleaseAll(){for(const id of [...modelHeldKeys.keys()])modelReleasePointer(id);}
const modelJavaReleaseBase=pocketJavaReleaseAll;
pocketJavaReleaseAll=function(){modelReleaseAll();return modelJavaReleaseBase();};
function modelGamepadMarkup(){return '<section class="model-gamepad" aria-label="游戏触控手柄"><div class="model-dpad">'+[['dir:up','▲'],['dir:left','◀'],['ok','确认'],['dir:right','▶'],['dir:down','▼']].map(([a,t])=>'<button data-game-control="'+a+'" aria-label="游戏手柄 '+t+'">'+t+'</button>').join('')+'</div><div class="model-game-actions"><button data-game-control="soft:left">左软键</button><button data-game-control="soft:right">右软键</button><button data-game-control="home">手机菜单</button><button data-world-face="game">游戏近景</button></div><details><summary>数字键盘</summary><div class="model-number-pad">'+['1','2','3','4','5','6','7','8','9','*','0','#'].map(k=>'<button data-game-control="digit:'+k+'">'+k+'</button>').join('')+'</div></details></section>';}
function syncModelGamepad(){const shell=document.querySelector('#pocket-model-host > .shop3d-play');if(!shell)return;let pad=shell.querySelector('.model-gamepad');const active=shop3dPlayActive&&['java','arcade','snake'].includes(phoneState.app);if(!active)modelReleaseAll();if(!pad&&active){shell.insertAdjacentHTML('beforeend',modelGamepadMarkup());pad=shell.querySelector('.model-gamepad');}if(pad)pad.hidden=!active;shell.classList.toggle('model-gaming',active);}
document.addEventListener('pointerdown',e=>{const el=e.target.closest?.('[data-game-control],[data-model-action]');if(!el||!blenderWorld?.powered||blenderWorld.locked||blenderWorld.closed)return;const action=el.dataset.gameControl||el.dataset.modelAction;if(blenderWorld.allowedKey&&!blenderWorld.allowedKey(action))return;const code=modelJavaCode(action);if(phoneState.app!=='java'||!validPocketJavaKey(code))return;e.preventDefault();e.stopPropagation();el.dataset.modelPointer='yes';try{el.setPointerCapture(e.pointerId);}catch{}modelHeldKeys.set(e.pointerId,{code,el});el.classList.add('is-held');pocketJavaMessage('key',code,true);},true);
for(const event of ['pointerup','pointercancel','lostpointercapture'])document.addEventListener(event,e=>modelReleasePointer(e.pointerId),true);
document.addEventListener('click',e=>{const el=e.target.closest?.('[data-game-control],[data-model-action]');if(!el)return;if(el.dataset.modelPointer==='yes'&&e.detail!==0){delete el.dataset.modelPointer;e.preventDefault();e.stopImmediatePropagation();return;}if(el.dataset.gameControl){e.preventDefault();e.stopImmediatePropagation();blenderKey(el.dataset.gameControl);}},true);
window.addEventListener('blur',modelReleaseAll);
document.addEventListener('visibilitychange',()=>{if(document.hidden)modelReleaseAll();});
